class EjercicioResuelto {
  final String id;
  final String? rutaImagen;
  final DateTime fecha;
  String autor;
  String modeloUsado;
  String? nombrePptUsado;
  String? solucion;
  bool procesando;

  EjercicioResuelto({
    required this.id,
    this.rutaImagen,
    required this.fecha,
    this.autor = 'Local',
    required this.modeloUsado,
    this.nombrePptUsado,
    this.solucion,
    this.procesando = true,
  });

  Map<String, dynamic> toJson() => {
        'id': id,
        'rutaImagen': rutaImagen,
        'fecha': fecha.toIso8601String(),
        'autor': autor,
        'modeloUsado': modeloUsado,
        'nombrePptUsado': nombrePptUsado,
        'solucion': solucion,
        'procesando': procesando,
      };

  factory EjercicioResuelto.fromJson(Map<String, dynamic> json) =>
      EjercicioResuelto(
        id: json['id'] ?? DateTime.now().millisecondsSinceEpoch.toString(),
        rutaImagen: json['rutaImagen'],
        fecha: DateTime.tryParse(json['fecha'] ?? '') ?? DateTime.now(),
        autor: json['autor'] ?? 'Compañero',
        modeloUsado: json['modeloUsado'] ?? 'gemini-3.1-pro-preview',
        nombrePptUsado: json['nombrePptUsado'],
        solucion: json['solucion'],
        procesando: json['procesando'] ?? false,
      );
}

class PptCompartido {
  final String id;
  final String nombre;
  final String autor;
  final String textoExtraido;
  final DateTime fecha;

  PptCompartido({
    required this.id,
    required this.nombre,
    required this.autor,
    required this.textoExtraido,
    required this.fecha,
  });

  Map<String, dynamic> toJson() => {
        'id': id,
        'nombre': nombre,
        'autor': autor,
        'textoExtraido': textoExtraido,
        'fecha': fecha.toIso8601String(),
      };

  factory PptCompartido.fromJson(Map<String, dynamic> json) => PptCompartido(
        id: json['id'] ?? DateTime.now().millisecondsSinceEpoch.toString(),
        nombre: json['nombre'] ?? 'Presentacion PPT',
        autor: json['autor'] ?? 'Compañero',
        textoExtraido: json['textoExtraido'] ?? '',
        fecha: DateTime.tryParse(json['fecha'] ?? '') ?? DateTime.now(),
      );
}

