        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
              content: Text('Todas las soluciones fueron eliminadas.')),
        );
      }
    }
  }

  String _extraerTextoDeBytesPptx(List<int> bytes) {
    final archive = ZipDecoder().decodeBytes(bytes);
    final slidesBuffer = StringBuffer();
    int numSlide = 0;

    final slideFiles = archive.files
        .where((f) =>
            f.name.startsWith('ppt/slides/slide') && f.name.endsWith('.xml'))
        .toList();
    slideFiles.sort((a, b) => a.name.compareTo(b.name));

    final regExpTexto = RegExp(r'<a:t[^>]*>(.*?)</a:t>');

    for (final file in slideFiles) {
      numSlide++;
      final content =
          utf8.decode(file.content as List<int>, allowMalformed: true);
      final matches = regExpTexto.allMatches(content);
      final textoSlide = matches
          .map((m) => m.group(1) ?? '')
          .where((t) => t.trim().isNotEmpty)
          .join(' ');
      if (textoSlide.isNotEmpty) {
        slidesBuffer.writeln('--- Diapositiva $numSlide ---');
        slidesBuffer.writeln(textoSlide);
      }
    }
    return slidesBuffer.toString().trim();
  }

  Future<void> _activarYCompartirPpt({
    required String nombre,
    required String textoExtraido,
    required String autor,
    String? base64Pdf,
    bool compartirEnSala = true,
  }) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('ppt_nombre', nombre);
    await prefs.setString('ppt_autor', autor);
    await prefs.setString('ppt_texto', textoExtraido);
    if (base64Pdf != null) {
      await prefs.setString('pdf_base64', base64Pdf);
    } else {
      await prefs.remove('pdf_base64');
    }

    final nuevoPpt = PptCompartido(
      id: '${nombre}_$autor',
      nombre: nombre,
      autor: autor,
      textoExtraido: textoExtraido,
      fecha: DateTime.now(),
    );

    if (mounted) {
      setState(() {
        _nombreArchivoContexto = nombre;
        _autorPptActivo = autor;
        _textoExtraidoPpt = textoExtraido;
        _base64PdfContexto = base64Pdf;
        _pptsDeLaSala.removeWhere((p) => p.nombre == nombre);
        _pptsDeLaSala.insert(0, nuevoPpt);
      });
    }
    await _guardarHistorialLocal();

    if (compartirEnSala && _codigoSala.isNotEmpty && textoExtraido.isNotEmpty) {
      await _publicarPptEnSala(nuevoPpt);
    }
  }

  // Abre el selector oficial nativo de Android (SAF / Google Drive) mediante MainActivity.kt
  // sin usar paquetes externos que rompan GitHub Actions.
  Future<void> _seleccionarPptDesdeGoogleDriveNativo() async {
    try {
      final result =
          await _driveChannel.invokeMapMethod<String, dynamic>('pickDocument');
      if (result == null) return;

      final nombre = (result['name'] as String?) ?? 'Presentacion_Drive.pptx';
      final b64Data = (result['base64'] as String?) ?? '';
      if (b64Data.isEmpty) {
        throw Exception('El archivo seleccionado en Drive esta vacio.');
      }

      final bytes = base64Decode(b64Data);
      final ext = nombre.toLowerCase();

      if (ext.endsWith('.pptx')) {
        final textoFinal = _extraerTextoDeBytesPptx(bytes);
        if (textoFinal.isEmpty) {
          throw Exception('No se encontro texto legible dentro del PPTX.');
        }
        await _activarYCompartirPpt(
          nombre: nombre,
          textoExtraido: textoFinal,
          autor: _aliasUsuario,
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
                content: Text(
                    'PPT cargado desde Google Drive y compartido en la sala: $nombre')),
          );
        }
      } else if (ext.endsWith('.pdf')) {
        await _activarYCompartirPpt(
          nombre: nombre,
          textoExtraido:
              '[Documento PDF cargado desde Drive por $_aliasUsuario: $nombre]',
          autor: _aliasUsuario,
          base64Pdf: b64Data,
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('PDF cargado desde Google Drive: $nombre')),
          );
        }
      } else {
        String texto = '';
        try {
          texto = _extraerTextoDeBytesPptx(bytes);
        } catch (_) {
          texto = utf8.decode(bytes, allowMalformed: true);
        }
        await _activarYCompartirPpt(
          nombre: nombre,
          textoExtraido: texto,
          autor: _aliasUsuario,
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
                content: Text(
                    'Archivo cargado desde Google Drive y compartido: $nombre')),
          );
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error al abrir desde Google Drive: $e')),
        );
      }
    }
  }

  Future<void> _importarLinkGoogleDriveOSlides(String urlRaw) async {
    final link = urlRaw.trim();
    if (link.isEmpty) return;

    try {
      await _esperarConexionRedActiva();
      final matchId = RegExp(r'/d/([a-zA-Z0-9_-]+)').firstMatch(link) ??
          RegExp(r'id=([a-zA-Z0-9_-]+)').firstMatch(link);

      if (matchId == null) {
        throw Exception(
            'Enlace no reconocido. Asegurate de pegar un enlace de Google Drive o Google Slides.');
      }

      final docId = matchId.group(1)!;
      String textoDescargado = '';
      String nombreDoc =
          'Google_Drive_${docId.substring(0, min(5, docId.length))}.pptx';

      if (link.contains('presentation')) {
        final exportTxtUrl = Uri.parse(
            'https://docs.google.com/presentation/d/$docId/export/txt');
        final resTxt = await http.get(exportTxtUrl);
        if (resTxt.statusCode == 200 && resTxt.body.trim().isNotEmpty) {
          textoDescargado = resTxt.body.trim();
          nombreDoc =
              'Google_Slides_${docId.substring(0, min(5, docId.length))}.pptx';
        } else {
          final exportPptxUrl = Uri.parse(
              'https://docs.google.com/presentation/d/$docId/export/pptx');
          final resPptx = await http.get(exportPptxUrl);
          if (resPptx.statusCode == 200) {
            textoDescargado = _extraerTextoDeBytesPptx(resPptx.bodyBytes);
          }
        }
      }

      if (textoDescargado.isEmpty) {
        final driveDownloadUrl = Uri.parse(
            'https://drive.google.com/uc?export=download&id=$docId');
        final resDrive = await http.get(driveDownloadUrl);
        if (resDrive.statusCode == 200) {
          try {
            textoDescargado = _extraerTextoDeBytesPptx(resDrive.bodyBytes);
          } catch (_) {
            textoDescargado =
                utf8.decode(resDrive.bodyBytes, allowMalformed: true);
          }
        }
      }

      if (textoDescargado.trim().isEmpty) {
        throw Exception(
            'No se pudo descargar el enlace (verifica que el archivo en Drive tenga acceso "Cualquier persona con el enlace").');
      }

      await _activarYCompartirPpt(
        nombre: nombreDoc,
        textoExtraido: textoDescargado,
        autor: _aliasUsuario,
      );

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content: Text(
                  'Presentacion importada de Google Drive y compartida en la sala: $nombreDoc')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error al importar de Drive: $e')),
        );
      }
    }
  }

  Future<void> _cargarArchivoPptOPdf(File archivo) async {
    final nombre = archivo.path.split('/').last;
    final ext = nombre.toLowerCase();

    try {
      if (ext.endsWith('.pptx')) {
        final bytes = await archivo.readAsBytes();
        final textoFinal = _extraerTextoDeBytesPptx(bytes);
        if (textoFinal.isEmpty) {
          throw Exception('No se encontro texto legible dentro del PPTX.');
        }

        await _activarYCompartirPpt(
          nombre: nombre,
          textoExtraido: textoFinal,
          autor: _aliasUsuario,
        );

        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
                content:
                    Text('PPT cargado y compartido con la sala: $nombre')),
          );
        }
      } else if (ext.endsWith('.pdf')) {
        final bytes = await archivo.readAsBytes();
        final b64 = base64Encode(bytes);
        await _activarYCompartirPpt(
          nombre: nombre,
          textoExtraido: '[Documento PDF cargado por $_aliasUsuario: $nombre]',
          autor: _aliasUsuario,
          base64Pdf: b64,
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('Documento PDF de apoyo cargado: $nombre')),
          );
        }
      } else if (ext.endsWith('.txt') || ext.endsWith('.md')) {
        final texto = await archivo.readAsString();
        await _activarYCompartirPpt(
          nombre: nombre,
          textoExtraido: texto,
          autor: _aliasUsuario,
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('Apuntes cargados y compartidos: $nombre')),
          );
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error al leer el archivo: $e')),
        );
      }
    }
  }

  Future<void> _quitarPptCargado() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove('ppt_nombre');
    await prefs.remove('ppt_autor');
    await prefs.remove('ppt_texto');
    await prefs.remove('pdf_base64');
    if (mounted) {
      setState(() {
        _nombreArchivoContexto = '';
        _autorPptActivo = '';
        _textoExtraidoPpt = '';
        _base64PdfContexto = null;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
            content: Text(
                'PPT desvinculado. Ahora Gemini respondera sin material externo.')),
      );
    }
  }

  Future<List<File>> _buscarArchivosPptEnTelefono() async {
    final rutasBusqueda = [
      '/storage/emulated/0/Download',
      '/storage/emulated/0/Documents',
      '/storage/emulated/0/Pictures/SayCheese',
    ];
    final List<File> encontrados = [];

    for (final ruta in rutasBusqueda) {
      try {
        final dir = Directory(ruta);
        if (await dir.exists()) {
          final entidades = dir.listSync(recursive: false);
          for (final ent in entidades) {
            if (ent is File) {
              final p = ent.path.toLowerCase();
              if (p.endsWith('.pptx') ||
                  p.endsWith('.pdf') ||
                  p.endsWith('.txt')) {
                encontrados.add(ent);
              }
            }
          }
        }
      } catch (_) {}
    }
    encontrados
        .sort((a, b) => b.lastModifiedSync().compareTo(a.lastModifiedSync()));
    return encontrados;
  }

