  String _topicoNtfyDeSala(String sala) {
    final limpio =
        sala.trim().toUpperCase().replaceAll(RegExp(r'[^A-Z0-9_-]'), '');
    final hash = base64Url
        .encode(utf8.encode('saycheese_sync_v9_$limpio'))
        .replaceAll('=', '')
        .replaceAll('-', '')
        .replaceAll('_', '');
    return 'saycheese_v9_${limpio}_$hash';
  }

  Future<void> _publicarEventoEnSala(Map<String, dynamic> payload) async {
    if (_codigoSala.trim().isEmpty) return;
    try {
      await _esperarConexionRedActiva();
      final topic = _topicoNtfyDeSala(_codigoSala);
      final url = Uri.parse('https://ntfy.sh/$topic');
      await http
          .post(
            url,
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 15));
    } catch (_) {}
  }

  Future<void> _publicarSolucionIndividualEnSala(EjercicioResuelto e) async {
    if (_codigoSala.trim().isEmpty || e.procesando || e.solucion == null) {
      return;
    }
    await _publicarEventoEnSala({
      'tipo': 'solucion',
      'emisor': _aliasUsuario,
      'item': {
        'id': e.id,
        'fecha': e.fecha.toIso8601String(),
        'autor': e.autor,
        'modeloUsado': e.modeloUsado,
        'nombrePptUsado': e.nombrePptUsado,
        'solucion': e.solucion,
        'procesando': false,
      },
    });
  }

  Future<void> _publicarPptEnSala(PptCompartido ppt) async {
    if (_codigoSala.trim().isEmpty) return;
    final textoSeguro = ppt.textoExtraido.length > 28000
        ? ppt.textoExtraido.substring(0, 28000)
        : ppt.textoExtraido;

    await _publicarEventoEnSala({
      'tipo': 'ppt',
      'emisor': _aliasUsuario,
      'ppt': {
        'id': ppt.id,
        'nombre': ppt.nombre,
        'autor': ppt.autor,
        'textoExtraido': textoSeguro,
        'fecha': ppt.fecha.toIso8601String(),
      },
    });
  }

  Future<void> _publicarEstadoCompletoEnSala() async {
    if (_codigoSala.trim().isEmpty) return;
    if (_nombreArchivoContexto.isNotEmpty && _textoExtraidoPpt.isNotEmpty) {
      await _publicarPptEnSala(PptCompartido(
        id: '${_nombreArchivoContexto}_$_aliasUsuario',
        nombre: _nombreArchivoContexto,
        autor: _autorPptActivo.isNotEmpty ? _autorPptActivo : _aliasUsuario,
        textoExtraido: _textoExtraidoPpt,
        fecha: DateTime.now(),
      ));
    }
    final misResueltos = _historial
        .where((e) => !e.procesando && e.solucion != null)
        .take(8)
        .toList();
    for (final item in misResueltos) {
      await _publicarSolucionIndividualEnSala(item);
    }
  }

  Future<void> _sincronizarSalaCompartida({bool silencioso = false}) async {
    if (_codigoSala.trim().isEmpty) return;
    if (!silencioso && mounted) setState(() => _sincronizando = true);

    try {
      await _esperarConexionRedActiva();
      final topic = _topicoNtfyDeSala(_codigoSala);
      final url = Uri.parse('https://ntfy.sh/$topic/json?poll=1&since=12h');
      final res = await http.get(url).timeout(const Duration(seconds: 15));

      if (res.statusCode == 200 && res.body.isNotEmpty) {
        final lineas = res.body.split('\n');
        bool huboCambios = false;

        for (final linea in lineas) {
          if (linea.trim().isEmpty) continue;
          try {
            final envoltorio = jsonDecode(linea) as Map<String, dynamic>;
            if (envoltorio['event'] != 'message') continue;
            final rawMsg = envoltorio['message'] as String? ?? '';
            if (rawMsg.isEmpty) continue;

            final data = jsonDecode(rawMsg) as Map<String, dynamic>;
            final tipo = data['tipo'] as String? ?? '';

            if (tipo == 'solucion' && data['item'] != null) {
              final itemRemoto = EjercicioResuelto.fromJson(
                  data['item'] as Map<String, dynamic>);
              if (_idsEliminados.contains(itemRemoto.id)) continue;

              final idx =
                  _historial.indexWhere((loc) => loc.id == itemRemoto.id);
              if (idx == -1) {
                _historial.add(itemRemoto);
                huboCambios = true;
              } else if (_historial[idx].solucion != itemRemoto.solucion &&
                  itemRemoto.solucion != null) {
                _historial[idx].solucion = itemRemoto.solucion;
                _historial[idx].modeloUsado = itemRemoto.modeloUsado;
                _historial[idx].nombrePptUsado = itemRemoto.nombrePptUsado;
                _historial[idx].autor = itemRemoto.autor;
                _historial[idx].procesando = false;
                huboCambios = true;
              }
            } else if (tipo == 'ppt' && data['ppt'] != null) {
              final pptRemoto =
                  PptCompartido.fromJson(data['ppt'] as Map<String, dynamic>);
              final existePpt = _pptsDeLaSala
                  .indexWhere((p) => p.nombre == pptRemoto.nombre);
              if (existePpt == -1) {
                _pptsDeLaSala.insert(0, pptRemoto);
                huboCambios = true;
              } else if (_pptsDeLaSala[existePpt].textoExtraido !=
                  pptRemoto.textoExtraido) {
                _pptsDeLaSala[existePpt] = pptRemoto;
                huboCambios = true;
              }

              if (_nombreArchivoContexto != pptRemoto.nombre &&
                  pptRemoto.textoExtraido.isNotEmpty) {
                _nombreArchivoContexto = pptRemoto.nombre;
                _autorPptActivo = pptRemoto.autor;
                _textoExtraidoPpt = pptRemoto.textoExtraido;
                _base64PdfContexto = null;
                final prefs = await SharedPreferences.getInstance();
                await prefs.setString('ppt_nombre', _nombreArchivoContexto);
                await prefs.setString('ppt_autor', _autorPptActivo);
                await prefs.setString('ppt_texto', _textoExtraidoPpt);
                huboCambios = true;
              }
            } else if (tipo == 'eliminar_solucion' && data['id'] != null) {
              final idBorrar = data['id'].toString();
              if (!_idsEliminados.contains(idBorrar)) {
                _idsEliminados.add(idBorrar);
                _historial.removeWhere((e) => e.id == idBorrar);
                huboCambios = true;
              }
            }
          } catch (_) {}
        }

        if (huboCambios) {
          _historial.sort((a, b) => b.fecha.compareTo(a.fecha));
          if (mounted) setState(() {});
          await _guardarHistorialLocal();
        }
      }

      if (!silencioso) {
        await _publicarEstadoCompletoEnSala();
      }
    } catch (_) {
    } finally {
      if (!silencioso && mounted) setState(() => _sincronizando = false);
    }
  }

