  String _generarCodigoSalaAleatorio() {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    final rnd = Random();
    final sufijo =
        List.generate(4, (_) => chars[rnd.nextInt(chars.length)]).join();
    return 'SALA-$sufijo';
  }

  void _mostrarDialogoSalaCompartida() {
    final aliasController = TextEditingController(text: _aliasUsuario);
    final unirseController = TextEditingController(text: _codigoSala);
    bool modoUnirse = true;

    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialogState) => AlertDialog(
          title: const Text('Salas en Vivo (Respuestas + PPTs)'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                TextField(
                  controller: aliasController,
                  decoration: const InputDecoration(
                    labelText: 'Tu Nombre o Alias',
                    hintText: 'Ej: conrads',
                    prefixIcon: Icon(Icons.person),
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 14),
                Row(
                  children: [
                    Expanded(
                      child: ChoiceChip(
                        label: const Text('Unirse a Sala'),
                        selected: modoUnirse,
                        onSelected: (_) =>
                            setDialogState(() => modoUnirse = true),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: ChoiceChip(
                        label: const Text('Crear mi Sala'),
                        selected: !modoUnirse,
                        onSelected: (_) {
                          setDialogState(() {
                            modoUnirse = false;
                            if (unirseController.text.trim().isEmpty) {
                              unirseController.text =
                                  _generarCodigoSalaAleatorio();
                            }
                          });
                        },
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 12),
                if (modoUnirse) ...[
                  const Text(
                    'Ingresa el codigo de la sala de tu compañero para ver sus respuestas y los PPTs que suba en tiempo real:',
                    style: TextStyle(fontSize: 12, color: Colors.grey),
                  ),
                  const SizedBox(height: 8),
                  TextField(
                    controller: unirseController,
                    textCapitalization: TextCapitalization.characters,
                    decoration: const InputDecoration(
                      labelText: 'Codigo de la sala a unirse',
                      hintText: 'Ej: SALA-8X4P',
                      prefixIcon: Icon(Icons.login),
                      border: OutlineInputBorder(),
                    ),
                  ),
                ] else ...[
                  const Text(
                    'Comparte este codigo con tu compañero para que vea tus respuestas y tus PPTs:',
                    style: TextStyle(fontSize: 12, color: Colors.grey),
                  ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: unirseController,
                          textCapitalization: TextCapitalization.characters,
                          decoration: const InputDecoration(
                            labelText: 'Codigo de tu nueva sala',
                            border: OutlineInputBorder(),
                          ),
                        ),
                      ),
                      IconButton(
                        icon: const Icon(Icons.casino),
                        tooltip: 'Generar otro codigo',
                        onPressed: () {
                          setDialogState(() {
                            unirseController.text =
                                _generarCodigoSalaAleatorio();
                          });
                        },
                      ),
                    ],
                  ),
                ],
                if (_codigoSala.isNotEmpty) ...[
                  const SizedBox(height: 16),
                  OutlinedButton.icon(
                    style: OutlinedButton.styleFrom(
                      foregroundColor: Colors.redAccent,
                      side: const BorderSide(color: Colors.redAccent),
                    ),
                    icon: const Icon(Icons.logout),
                    label: Text('Abandonar Sala ($_codigoSala)'),
                    onPressed: () async {
                      Navigator.pop(ctx);
                      await _abandonarSala();
                    },
                  ),
                ],
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Cancelar'),
            ),
            FilledButton.icon(
              icon: Icon(modoUnirse ? Icons.group_add : Icons.add_link),
              label: Text(modoUnirse ? 'Unirse a Sala' : 'Activar Sala'),
              onPressed: () async {
                final nuevoAlias = aliasController.text.trim().isEmpty
                    ? 'conrads'
                    : aliasController.text.trim();
                final nuevaSala = unirseController.text.trim().toUpperCase();
                final prefs = await SharedPreferences.getInstance();
                await prefs.setString('sala_compartida', nuevaSala);
                await prefs.setString('alias_usuario', nuevoAlias);
                setState(() {
                  _codigoSala = nuevaSala;
                  _aliasUsuario = nuevoAlias;
                });
                if (mounted) Navigator.pop(ctx);
                if (nuevaSala.isNotEmpty) {
                  await _publicarEstadoCompletoEnSala();
                  await _sincronizarSalaCompartida();
                  if (mounted) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                          content: Text(
                              'Conectado a la sala $nuevaSala como $nuevoAlias')),
                    );
                  }
                }
              },
            ),
          ],
        ),
      ),
    );
  }

